213:       stepMetaByPath.set(path, {
214:         name: typeof content.name === 'string' ? content.name : undefined,
215:         sha256: typeof content.sha256 === 'string' ? content.sha256 : undefined,
216:         sizeBytes: typeof content.size_bytes === 'number' ? content.size_bytes : undefined,
217:         format: typeof content.format === 'string' ? content.format : undefined,
218:       });
219:     } else if (step.event_type === 'tool_call') {
220:       const toolName = String(step.payload.tool_name ?? '');
221:       if (toolName !== 'generate_document') continue;
222:       const args =
223:         typeof step.payload.arguments === 'object' && step.payload.arguments !== null
224:           ? (step.payload.arguments as Record<string, unknown>)
225:           : {};
226:       const filename = typeof args.filename === 'string' ? args.filename : '';
227:       const bodyText = typeof args.content === 'string' ? args.content : '';
228:       if (filename && bodyText) {
229:         stepMetaByPath.set(`name:${filename}`, {
230:           name: filename,
231:           preview: bodyText,
232:           format: typeof args.format === 'string' ? args.format : undefined,
233:         });
234:       }
235:     }
236:   }
237: 
238:   const items: DeliverableItem[] = [];
239:   const seenPaths = new Set<string>();
240: 
241:   for (const art of artifacts) {
242:     seenPaths.add(art.path);
243:     const baseName = art.path.split('/').pop() ?? art.path;
244:     const stepMeta = stepMetaByPath.get(art.path) ?? stepMetaByPath.get(`name:${baseName}`);
245:     const name = stepMeta?.name ?? baseName;
246:     const format = detectDeliverableFormat(name, stepMeta?.format);
247:     items.push({
248:       id: art.id,
249:       artifactId: art.id,
250:       name,
251:       path: art.path,
252:       sizeBytes: art.size_bytes || stepMeta?.sizeBytes || 0,
253:       sha256: stepMeta?.sha256 ?? null,
254:       preview: art.preview ?? stepMeta?.preview ?? null,
255:       format,
256:     });
257:   }
258: 
259:   for (const [pathKey, meta] of stepMetaByPath.entries()) {
260:     if (pathKey.startsWith('name:') || seenPaths.has(pathKey)) continue;
261:     const baseName = meta.name ?? pathKey.split('/').pop() ?? pathKey;
262:     const nameMeta = stepMetaByPath.get(`name:${baseName}`);
263:     const format = detectDeliverableFormat(baseName, meta.format ?? nameMeta?.format);
264:     items.push({
265:       id: `step-${pathKey}`,
266:       artifactId: null,
267:       name: baseName,
268:       path: pathKey,
269:       sizeBytes: meta.sizeBytes ?? 0,
270:       sha256: meta.sha256 ?? null,
271:       preview: meta.preview ?? nameMeta?.preview ?? null,
272:       format,
273:     });
274:   }
275: 
276:   return items;
277: }
